// Online says "{Count} online"
// in the language the app shows under cx.
func Online(cx *core.Scope, Count int) string { return For(cx).Online(Count) }

// Online is the package's Online in the language of msgs.
func (msgs Messages) Online(Count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.Online(Count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].Online; f != nil {
			return f(Count)
		}
		switch lang {
		case "", "en":
			return msgs.arg(i18n.FormatNumber("en", float64(Count))) + " online"
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(Count)) + " 在线"
		}
	}
}

